close all
clear

% to determine max shear and bending moments under moving load of 400 N

y_bar = 41.43 % mm %[output:0a4051c6]
I = 418352.209 % mm^4 %[output:6db3a2d9]

axle_offsets = [0, 176, 340, 516, 680, 856] %[output:526f1858]

L = 1250 % length of the beam %[output:1af19783]
s_values = -axle_offsets(end):1:L %[output:3a06fb2d]
num_locations = length(s_values) % number of locations along the beam %[output:408e87c5]
% array with all x values across the beam of length L
x = 0:1:L % mm %[output:04166297]

% total load of train
P_value = 400 %[output:4e981281]

h = 0 %[output:2bd71924]

P_axle = (P_value/6) * ones(1, 6) %[output:18995b5e]

SFDi = zeros(num_locations, length(x)); % 1 SFD for each train location
BMDi = zeros(num_locations, length(x)); % 1 BMD for each train location

% these two take the largest of each of the 1201 stops along the beam
V_env = zeros(size(x));
M_env = zeros(size(x));

% start from left most axle at -856 and right most axle just at left
% support

for i = 1:num_locations
    s = s_values(i);
    % disp("x = " + s)
    axle_pos = s + axle_offsets;
    on_bridge = (axle_pos >= 0) & (axle_pos <= L);
    if ~any(on_bridge)
        continue
    end

    % loads from axles that are actually on the bridge
    P = zeros(1,6);
    for k = 1:6
        if on_bridge(k)
            P(k) = P_axle(k);
        end
    end

    % left reaction
    R_A = 0;
    for k = 1:6
        R_A = R_A + P(k) * (L - axle_pos(k)) / L;
    end
    % disp(R_A)

    V = R_A * ones(1, length(x));

    % shear forces
    
    for k = 1:6
        if on_bridge(k)
            for j = 1:length(x)
                if x(j) >= axle_pos(k)
                    V(j) = V(j) - P(k);
                end
            end
        end
    end
    
    % disp("This is V")
    % disp(V)
    
    % moments (area under shear)
    M = R_A * x;
    for k = 1:6
        if on_bridge(k)
            % searched up the statics formula for moment because
            % trapezoidal area was not working
            M = M - P(k) * max(x - axle_pos(k), 0);
        end
    end

    % store shear and moment
    SFDi(i,:) = V;
    BMDi(i,:) = M;

    % fprintf('R_A = %.2f, sum(P) - R_A = %.2f, sum(P) = %.2f\n', R_A, sum(P)-R_A, sum(P));
    % fprintf('V(end) = %.2f (should be -R_B = %.2f)\n', V(end), -(sum(P)-R_A));
    % fprintf('M(1) = %.4f, M(end) = %.4f\n', M(1), M(end));
end

% find max shear and moment and where they occur

% this finds the max shear (abs value) and moment in each row of the SFDi
% and BMDi
abs_SFDi = abs(SFDi) %[output:8a1cf7b7]
V_env = max(abs_SFDi, [], 1);
M_env = max(BMDi, [], 1);

% max shear and max moment in ALL!
max_shear = max(abs_SFDi, [], "all") %[output:8eae2be1]
max_moment = max(BMDi, [], "all") %[output:7e5483d9]

fprintf('length(x) = %d, x(end) = %d\n', length(x), x(end)); %[output:2a0655f3]
fprintf('length(M_env) = %d, length(V_env) = %d\n', length(M_env), length(V_env)); %[output:7d286f6e]

% envelopes
figure, plot(x, M_env), grid on, title("Bending Moment Envelope") %[output:7454620e]
figure, plot(x, V_env), grid on, title("Shear Force Envelope") %[output:565f0e27]

% max shear
[maxV, idxV] = max(abs(SFDi(:)));
[rV, cV] = ind2sub(size(SFDi), idxV);
fprintf('Max |V| = %.2f N at x = %d mm, train position s = %d mm\n', ... %[output:group:51167dea] %[output:365a26c7]
    maxV, x(cV), s_values(rV)); %[output:group:51167dea] %[output:365a26c7]

% max moment
[maxM, idxM] = max(BMDi(:));
[rM, cM] = ind2sub(size(BMDi), idxM);
fprintf('Max M = %.2f N*mm at x = %d mm, train position s = %d mm\n', ... %[output:group:1b07620c] %[output:2e29935c]
    maxM, x(cM), s_values(rM)); %[output:group:1b07620c] %[output:2e29935c]




